#!/usr/bin/env bash
# riverxia.sh: terminal version of riverxia.sh (the website). generated by build.py from tui/riverxia.sh.
#   curl -s riverxia.sh | bash          or          wget riverxia.sh; bash index.html
#   (wget riverxia.sh/riverxia.sh; bash riverxia.sh also works)
#   keys: h/l or arrows = tabs, j/k = move, enter = open post, t = filter by tag, q = quit
#   bash riverxia.sh --plain            dump everything as plain text (also what you get without a tty)
#@DATA@

fetch() { if command -v curl >/dev/null 2>&1; then curl -fsSL "$1"; else wget -qO- "$1"; fi; }
has_tty() { { : </dev/tty; } 2>/dev/null; }

# markup in TEXT_n: "## heading", "* bullet", blank line between paragraphs. pretty=1 adds colour
fmt_text() { # text width pretty
  local text=$1 w=$2 pretty=$3 line l first
  local o='' g='' y='' r=''
  [ "$pretty" = 1 ] && { o=$'\e[1;38;5;208m'; y=$'\e[93m'; r=$'\e[0m'; g=$'\e[92m'; }
  while IFS= read -r line; do
    case $line in
      '## '*) printf '%s%s%s\n' "$o" "${line#\#\# }" "$r" ;;
      '* '*)
        first=1
        while IFS= read -r l; do
          if [ $first = 1 ]; then printf '%s*%s %s\n' "$y" "$r" "$l"; first=0; else printf '  %s\n' "$l"; fi
        done < <(printf '%s\n' "${line#\* }" | fold -s -w $((w - 2))) ;;
      '') echo ;;
      *) printf '%s\n' "$line" | fold -s -w "$w" ;;
    esac
  done <<<"$1"
}

all_tags() { local t; for t in "${P_TAGS[@]}"; do tr ',' '\n' <<<"$t"; done | sort | uniq -c | sort -k1,1nr -k2 | awk '{print $2}'; }

if [ "${1:-}" = --plain ] || ! { [ -t 1 ] && has_tty; }; then
  echo "~*~ hi, i'm river ~*~   $SITE"
  for i in 0 2 3 4; do
    echo; n="TEXT_$i"; fmt_text "${!n}" 78 0
  done
  echo; echo "## posts"
  for i in "${!P_SLUG[@]}"; do printf '* %s  %s [%s]\n  %s/%s.html\n' "${P_DATE[$i]}" "${P_TITLE[$i]}" "${P_TAGS[$i]}" "$BLOG" "${P_SLUG[$i]}"; done
  exit 0
fi

# ---- tui ----
BOLD=$'\e[1m'; RST=$'\e[0m'; DIM=$'\e[38;5;110m'; PINK=$'\e[95m'; LIME=$'\e[92m'; YEL=$'\e[93m'; REV=$'\e[7m'
tab=0; sel=0; top=0; tag=""; LINES_=()

cleanup() { printf '\e[?25h\e[?1049l'; stty sane 2>/dev/null; }
trap cleanup EXIT
trap 'redraw=1' WINCH
printf '\e[?1049h\e[?25l'

visible_posts() { VIS=(); local i; for i in "${!P_SLUG[@]}"; do
  if [ -z "$tag" ] || [[ ",${P_TAGS[$i]}," == *",$tag,"* ]]; then VIS+=("$i"); fi; done; }

build_lines() { # fills LINES_ (and SELLINE for the posts tab)
  LINES_=(); SELLINE=-1
  local l n k i
  if [ $tab = 1 ]; then
    visible_posts
    LINES_+=("${DIM}filter: ${RST}${YEL}${tag:-all}${RST}${DIM}  (t: next tag)  ${#VIS[@]} posts${RST}" "")
    ((sel >= ${#VIS[@]})) && sel=$((${#VIS[@]} - 1)); ((sel < 0)) && sel=0
    k=0
    for i in "${VIS[@]}"; do
      if [ $k = "$sel" ]; then SELLINE=${#LINES_[@]}; LINES_+=("${REV}> ${P_DATE[$i]}  ${P_TITLE[$i]}${RST}"); else LINES_+=("  ${DIM}${P_DATE[$i]}${RST}  ${P_TITLE[$i]}"); fi
      LINES_+=("    ${DIM}${P_TAGS[$i]//,/ }${RST}")
      k=$((k + 1))
    done
  else
    n="TEXT_$tab"
    while IFS= read -r l; do LINES_+=("$l"); done < <(fmt_text "${!n}" "$W" 1)
  fi
}

draw() {
  local rows cols h i name bar=""
  rows=$(tput lines); cols=$(tput cols); W=$((cols - 4)); ((W > 90)) && W=90; ((W < 20)) && W=20
  build_lines
  h=$((rows - 5)); ((h < 3)) && h=3
  if ((SELLINE >= 0)); then
    ((SELLINE < top + 2)) && top=$((SELLINE - 2)); ((SELLINE >= top + h - 1)) && top=$((SELLINE - h + 2))
  fi
  ((top > ${#LINES_[@]} - h)) && top=$((${#LINES_[@]} - h)); ((top < 0)) && top=0
  for i in "${!TAB_NAMES[@]}"; do
    name=${TAB_NAMES[$i]}
    if [ "$i" = "$tab" ]; then bar+="${REV}${YEL} $((i + 1)) $name ${RST} "; else bar+="${DIM} $((i + 1)) $name ${RST} "; fi
  done
  printf '\e[H\e[2J'
  printf ' %s~*~ hi, i'"'"'m river ~*~%s  %s%s%s\n' "${BOLD}${LIME}" "$RST" "$PINK" "$SITE" "$RST"
  printf ' %s\n\n' "$bar"
  for ((i = top; i < top + h && i < ${#LINES_[@]}; i++)); do printf '  %s\n' "${LINES_[$i]}"; done
  printf '\e[%d;1H%s h/l tabs  j/k move  enter open  t tag  q quit %s' "$rows" "$DIM" "$RST"
}

open_post() {
  local i=${VIS[$sel]:-} url
  [ -z "$i" ] && return
  url="$BLOG/${P_SLUG[$i]}.md"
  printf '\e[?25h\e[?1049l'
  { fetch "$url" 2>/dev/null || echo "could not fetch $url"; } | if command -v less >/dev/null 2>&1; then less -R; else more; fi
  printf '\e[?1049h\e[?25l'
}

next_tag() {
  local tags t found=0 first="" nxt=""
  tags=(); while IFS= read -r t; do tags+=("$t"); done < <(all_tags)
  if [ -z "$tag" ]; then nxt=${tags[0]:-}; else
    for t in "${tags[@]}"; do [ $found = 1 ] && { nxt=$t; break; }; [ "$t" = "$tag" ] && found=1; done
  fi
  tag=$nxt; sel=0; top=0
}

redraw=1
while :; do
  ((redraw)) && { draw; redraw=0; }
  IFS= read -rsn1 k </dev/tty || break
  if [ "$k" = $'\e' ]; then IFS= read -rsn2 -t 0.05 rest </dev/tty; k="ESC$rest"; fi
  case $k in
    q|Q) break ;;
    l|ESC\[C|$'\t') tab=$(((tab + 1) % ${#TAB_NAMES[@]})); sel=0; top=0 ;;
    h|ESC\[D) tab=$(((tab + ${#TAB_NAMES[@]} - 1) % ${#TAB_NAMES[@]})); sel=0; top=0 ;;
    [1-9]) ((k <= ${#TAB_NAMES[@]})) && { tab=$((k - 1)); sel=0; top=0; } ;;
    j|ESC\[B) if [ $tab = 1 ]; then ((sel < ${#VIS[@]} - 1)) && sel=$((sel + 1)); else top=$((top + 1)); fi ;;
    k|ESC\[A) if [ $tab = 1 ]; then ((sel > 0)) && sel=$((sel - 1)); else ((top > 0)) && top=$((top - 1)); fi ;;
    ' '|ESC\[6) top=$((top + $(tput lines) - 6)) ;;
    g) top=0; sel=0 ;;
    G) top=999999; sel=$((${#VIS[@]} - 1)) ;;
    t|T) [ $tab = 1 ] && next_tag ;;
    ''|$'\n') [ $tab = 1 ] && open_post ;;
  esac
  redraw=1
done
